SINA_SMART["bacterio1-pyogenes"] = {"lecture":"bacterio1-pyogenes","title":"Streptococcus pyogenes","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"bacterio1-pyogenes:e1","text":"Lancefield: A = S. pyogenes, B = S. agalactiae, D = enterococci / S. bovis.","topic":"Streptococci and Lancefield groups","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-pyogenes:e2","text":"Haemolysis: β complete, α green (pneumococcus), γ none (enterococcus).","topic":"Streptococci and Lancefield groups","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-pyogenes:e0","text":"Streptococci: Gram-positive, catalase-negative cocci in chains.","topic":"Characteristics and identification","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-pyogenes:e3","text":"S. pyogenes: β-haemolytic, bacitracin S, PYR +, CAMP −, hippurate −.","topic":"Characteristics and identification","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-pyogenes:e4","text":"M protein: main antiphagocytic factor; emm typing.","topic":"Virulence factors","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-pyogenes:e5","text":"Streptolysins O and S, streptokinase, DNase, hyaluronidase.","topic":"Virulence factors","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-pyogenes:e6","text":"Superantigens (Spe) → toxic shock; erythrogenic toxins → scarlet fever.","topic":"Virulence factors","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-pyogenes:e7","text":"Pharyngitis most common; necrotising fasciitis and STSS invasive.","topic":"Clinical manifestations","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-pyogenes:e8","text":"Sequelae: rheumatic fever (mimicry) and glomerulonephritis (immune complexes).","topic":"Clinical manifestations","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-pyogenes:e10","text":"Severe invasive: IV penicillin + clindamycin.","topic":"Treatment and prevention","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-pyogenes:e9","text":"Penicillin: no resistance; 10 days for pharyngitis.","topic":"Treatment and prevention","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"ynp4dp":"a","yrrlo5":"a","9xlo82":"a","adih8n":"a","14v3hq8":"a","13mujzp":"a","1t385pn":"a","hha4aw":"a","14b09tr":"a","oquaxd":"a","ofxje5":"a","1wsocv0":"a","1uwcpo6":"a","199dvlt":"a","1fzahla":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"bacterio1-pyogenes:e1":{"s":0,"u":["Lancefield: A = S. pyogenes, B = S. agalactiae, D = enterococci / S. bovis.","Lancefield grouping uses the cell wall carbohydrate antigen: A = S. pyogenes (pharyngitis, scarlet fever, skin infections, necrotising fasciitis, toxic shock); B = S. agalactiae (neonatal sepsis and meningitis); C and G (pharyngitis, skin, zoonoses); D = enterococci and S. bovis (endocarditis, UTI); F/G/L = S. anginosus group (abscesses).","Haemolysis on blood agar : β = complete lysis, a clear zone ( S. pyogenes , S. agalactiae , S. aureus ); α = partial, green, from hydrogen peroxide oxidising haemoglobin ( S. pneumoniae ); γ = none ( Enterococcus faecalis )."],"dp":[]},"bacterio1-pyogenes:e2":{"s":0,"u":["Haemolysis: β complete, α green (pneumococcus), γ none (enterococcus).","Haemolysis on blood agar : β = complete lysis, a clear zone ( S. pyogenes , S. agalactiae , S. aureus ); α = partial, green, from hydrogen peroxide oxidising haemoglobin ( S. pneumoniae ); γ = none ( Enterococcus faecalis )."],"dp":[]},"bacterio1-pyogenes:e0":{"s":1,"u":["Streptococci: Gram-positive, catalase-negative cocci in chains.","Key tests: catalase negative (vs staphylococci); bacitracin sensitive (vs other β-haemolytic streptococci); PYR positive (pyrrolidonyl peptidase; also positive in enterococci); Lancefield group A ; CAMP negative and hippurate negative (vs group B); no growth in 6.5% NaCl and bile-aesculin negative (vs enterococci); bile insoluble (vs pneumococcus).","S. pyogenes : Gram-positive cocci in chains (0.6-1 µm), non-motile, non-sporing, some capsulated (hyaluronic acid); aerobic and facultatively anaerobic; fastidious (blood-enriched media, 37 °C, CO₂)."],"dp":[]},"bacterio1-pyogenes:e3":{"s":1,"u":["S. pyogenes: β-haemolytic, bacitracin S, PYR +, CAMP −, hippurate −.","Key tests: catalase negative (vs staphylococci); bacitracin sensitive (vs other β-haemolytic streptococci); PYR positive (pyrrolidonyl peptidase; also positive in enterococci); Lancefield group A ; CAMP negative and hippurate negative (vs group B); no growth in 6.5% NaCl and bile-aesculin negative (vs enterococci); bile insoluble (vs pneumococcus)."],"dp":[]},"bacterio1-pyogenes:e4":{"s":2,"u":["M protein: main antiphagocytic factor; emm typing.","Surface factors: M protein (antiphagocytic, the main virulence factor, basis of emm typing), protein F (binds fibronectin), lipoteichoic acid, hyaluronic acid capsule , C5a peptidase, streptococcal inhibitor of complement."],"dp":[]},"bacterio1-pyogenes:e5":{"s":2,"u":["Streptolysins O and S, streptokinase, DNase, hyaluronidase.","Secreted: streptolysins O and S (haemolysins, kill phagocytes), streptokinase (dissolves clots), DNases , hyaluronidase, SpeB protease and superantigen toxins (streptococcal pyrogenic exotoxins SpeA, SpeC and others) that activate T cells non-specifically: a cytokine storm in toxic shock , the rash of scarlet fever (erythrogenic toxins)."],"dp":[]},"bacterio1-pyogenes:e6":{"s":2,"u":["Superantigens (Spe) → toxic shock; erythrogenic toxins → scarlet fever.","Secreted: streptolysins O and S (haemolysins, kill phagocytes), streptokinase (dissolves clots), DNases , hyaluronidase, SpeB protease and superantigen toxins (streptococcal pyrogenic exotoxins SpeA, SpeC and others) that activate T cells non-specifically: a cytokine storm in toxic shock , the rash of scarlet fever (erythrogenic toxins)."],"dp":[]},"bacterio1-pyogenes:e7":{"s":3,"u":["Pharyngitis most common; necrotising fasciitis and STSS invasive.","Invasive : necrotising fasciitis (rapid destruction of fascia, severe pain, toxicity), streptococcal toxic shock syndrome , puerperal sepsis, bacteraemia, endocarditis.","Pharyngitis , the most common: sore throat, fever, tonsillar exudate, tender cervical nodes; 5-15% of people are asymptomatic carriers."],"dp":[]},"bacterio1-pyogenes:e8":{"s":3,"u":["Sequelae: rheumatic fever (mimicry) and glomerulonephritis (immune complexes).","Non-suppurative sequelae : acute rheumatic fever after untreated pharyngitis (fever, migratory polyarthritis, carditis, chorea; molecular mimicry) and post-streptococcal glomerulonephritis after pharyngitis or impetigo (haematuria, oedema, hypertension; immune complexes in glomeruli)."],"dp":[]},"bacterio1-pyogenes:e10":{"s":4,"u":["Severe invasive: IV penicillin + clindamycin.","Severe invasive disease (necrotising fasciitis, toxic shock): IV penicillin + clindamycin (clindamycin stops toxin synthesis) with surgery and supportive care.","Penicillin allergy: macrolides (resistance by mef efflux pumps) or clindamycin."],"dp":[]},"bacterio1-pyogenes:e9":{"s":4,"u":["Penicillin: no resistance; 10 days for pharyngitis.","Pharyngitis: 10 days of treatment to prevent rheumatic fever ; skin infections 7-10 days.","Penicillin allergy: macrolides (resistance by mef efflux pumps) or clindamycin."],"dp":[{"h":"Why penicillin still works after 80 years","t":"Many bacteria became resistant to penicillin within years, yet group A streptococci have never been found resistant. Their resistance would require altered penicillin-binding proteins, and the changes that lower penicillin binding seem to cost the organism too much fitness to persist. Macrolide resistance, by contrast, spreads easily through efflux genes on mobile elements. This is why penicillin remains first line and why a macrolide given to an allergic patient may fail: know the local macrolide resistance rate before relying on it. Source: the lecture's treatment table (no penicillin resistance; mef-mediated macrolide resistance)."}]}},"meta":{"ynp4dp":{"a":"relationship","vg":"bacterio1-pyogenes:e0/relationship/1"},"yrrlo5":{"a":"recall","vg":"bacterio1-pyogenes:e1/recall/1"},"9xlo82":{"a":"relationship","vg":"bacterio1-pyogenes:e2/relationship/1"},"adih8n":{"a":"recall","vg":"bacterio1-pyogenes:e1/recall/2"},"14v3hq8":{"a":"recall","vg":"bacterio1-pyogenes:e3/recall/1"},"13mujzp":{"a":"recall","vg":"bacterio1-pyogenes:e3/recall/2"},"1t385pn":{"a":"recall","vg":"bacterio1-pyogenes:e4/recall/1"},"hha4aw":{"a":"relationship","vg":"bacterio1-pyogenes:e6/relationship/1"},"14b09tr":{"a":"recall","vg":"bacterio1-pyogenes:e6/recall/1"},"oquaxd":{"a":"recall","vg":"bacterio1-pyogenes:e8/recall/1"},"ofxje5":{"a":"relationship","vg":"bacterio1-pyogenes:e8/relationship/1"},"1wsocv0":{"a":"recall","vg":"bacterio1-pyogenes:e10/recall/1"},"1uwcpo6":{"a":"recall","vg":"bacterio1-pyogenes:e9/recall/1"},"199dvlt":{"a":"recall","vg":"bacterio1-pyogenes:e10/recall/2"},"1fzahla":{"a":"recall","vg":"bacterio1-pyogenes:e1/recall/3"}},"explRev":"d2c8ccc474ab"};
